import { OpeningHoursItem, OperatingTime, OperatingTimeType } from "@parksandresorts/webapiproxy-types";
import { DateHelper } from "@/core/helpers";
import { sortBy } from "lodash-es";

export type OpeningWindow = {
  from: string;
  to: string;
};

export function getActiveOpeningWindowFromOpeningHours(openingHours: OpeningHoursItem, now: Date): OpeningWindow {
  const fullDay = {
    from: openingHours.opens,
    to: openingHours.closing,
  };
  return getActiveOpeningWindow(openingHours.passes ?? [], fullDay, now);
}

/**
 * Returns the currently active opening window from a list of OpeningWindows, and one representing the current day
 *
 * Resolution order:
 * 1. An active pass (its `from`–`to` span contains `now`)
 * 2. The earliest upcoming pass (not yet opened)
 * 3. The last passed pass (all passes have closed for today)
 * 4. (The opening hours for the day as a fallback, if no passes exists)
 */
export function getActiveOpeningWindow(
  openingWindows: Array<OpeningWindow>,
  fullDay: OpeningWindow,
  now: Date,
): OpeningWindow {
  if (openingWindows.length === 0) {
    return fullDay;
  }

  const sortedPasses = sortBy(openingWindows, "from");

  // if one pass ends when the next pass starts, merge them together
  const mergedPasses = sortedPasses.reduce((merged, next) => {
    const lastMerged = merged.at(-1);
    if (lastMerged?.to == next.from) {
      return [...merged.slice(0, -1), { from: lastMerged.from, to: next.to }];
    }
    return [...merged, next];
  }, [] as Array<OpeningWindow>);

  const activePass = mergedPasses.find(
    (pass) => DateHelper.isAfter(now, pass.from) && DateHelper.isBefore(now, pass.to),
  );
  const nextPass = mergedPasses.find((pass) => DateHelper.isAfter(pass.from, now));

  // The early return above guarantees openingWindows (and thus sortedPasses) is non-empty, making this assertion safe
  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
  const lastPass = mergedPasses.at(-1)!;

  return activePass ?? nextPass ?? lastPass;
}

/** Determines whether an OperatingTime is an official time, and thus presentable to the general public */
export function operatingTimeVisibleOnPublicWeb(operatingTime: OperatingTime) {
  return operatingTime.isOpenToPublic;
}

/**
 * Determines whether an OperatingTime is to be presented to visitors that have already entered the park
 *
 * Sometimes visitors are inside the park outside official opening hours. For these cases, the times should be
 * available to them, while the general public should not know of them. For example, "Early Entrance", "Magic Hours" and
 * days/hours where the park is reserved by an organization are times when the visitors inside the park should be in
 * the know, whereas people outside should not.
 */
export function operatingTimeVisibleInsidePark({ isOpenToPublic, operatingTimeType }: OperatingTime) {
  return (
    isOpenToPublic || // public times should be visible
    (operatingTimeType !== OperatingTimeType.RELATIVE_TIME && // relative times are for internal use (such as statistics), not relevant for guests
      operatingTimeType !== OperatingTimeType.NONE) // NONE means that the time should be excluded (fallback/error-case)
  );
}
