// The groupings are controlled (isExpanded + onClick), so the stories keep the expanded keys in local
// state and let the heading buttons toggle them.
const InteractiveCalendarGroupings = (props: ComponentProps<typeof CalendarGroupings>) => {
  const [expandedKeys, setExpandedKeys] = useState(
    () => new Set(props.groupings.filter((grouping) => grouping.isExpanded).map((grouping) => grouping.key)),
  );
  const toggle = (key: string) =>
    setExpandedKeys((previous) => {
      const next = new Set(previous);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });

  return (
    <div>
      <CalendarGroupings
        {...props}
        groupings={props.groupings.map((grouping) => ({
          ...grouping,
          isExpanded: expandedKeys.has(grouping.key),
          onClick: () => {
            grouping.onClick();
            toggle(grouping.key);
          },
        }))}
      />
    </div>
  );
};

const createGrouping = (
  key: string,
  heading: string,
  content: Array<CalendarGroupingContent>,
  overrides: Partial<CalendarGrouping> = {},
): CalendarGrouping => ({
  key,
  heading,
  content,
  scheduleListId: `${key}-list`,
  contentfulLabelId: key,
  isExpanded: true,
  onClick: action(`Grouping "${heading}" clicked`),
  ...overrides,
});

