/** Ticket to Ride is sold out for adults and children, so Ticket to Play is moved in front of it. */
export const SoldOutTicketsReordered: Story = {
  args: {
    groupings: [
      createGrouping("sold-out", "Tillgängliga biljetter 19 augusti", [
        { ...ticketToRide, productsPrices: { type: "groups", groups: soldOutGroups } },
        {
          ...ticketToPlay,
          productsPrices: {
            type: "groups",
            groups: [priceGroup("Day", "Hela dagen", "Åktid {parkOpens} - {parkClosing}", standardProducts)],
          },
        },
      ]),
    ],
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const headings = await canvas.findAllByRole("heading", { name: /Ticket to (Ride|Play)/ });
    await expect(headings.map((heading) => heading.textContent)).toEqual(["Ticket to Play", "Ticket to Ride"]);
  },
};

const onGroupingClick = fn();

export const TestToggleGrouping: Story = {
  args: {
    groupings: [createGrouping("toggle", "Restauranger", [snackbaren], { onClick: onGroupingClick })],
  },
  play: async ({ canvasElement }) => {
    onGroupingClick.mockClear();
    const canvas = within(canvasElement);
    const heading = canvas.getByRole("button", { name: "Restauranger" });
    const list = heading.nextElementSibling;

    await userEvent.click(heading);
    await expect(onGroupingClick).toHaveBeenCalledTimes(1);
    // The list collapses through a framer-motion height animation, so retry until it reaches 0.
    await waitFor(() => expect(list).toHaveStyle({ height: "0px" }));

    await userEvent.click(heading);
    // Expanding animates the height back and flips overflow to visible when the transition ends, so
    // waiting for that leaves every Chromatic capture on the same settled state.
    await waitFor(() => expect(list).toHaveStyle({ overflow: "visible" }));
  },
};
